/** (x, y) 격자 좌표의 장식 종류. 범위 밖이면 숲으로 친다. */
export function decoAt(deco: MapDeco, row: number, col: number): string {
  if (row < 0 || row >= deco.rows || col < 0 || col >= deco.cols) return '.';
  return deco.data[row * deco.cols + col] ?? '.';
}

/**
 * 손으로 배치한 지형지물 (그림에 그려져 있던 캠프·다리·천막).
 * 심에는 없는 순수 그림이라 유닛을 막지 않는다 — 통행은 마스크가 정한다.
 *   x, y = 타일 좌표 (y 는 맵 중앙이 0)
 *   w    = 그릴 가로 폭 (타일)
 *   clear= 이 반경(타일) 안엔 자동 산포 나무를 심지 않는다
 */
export interface MapProp {
  readonly name: string;
  readonly x: number;
  readonly y: number;
  readonly w: number;
  readonly clear?: number;
}


/**
 * 다리 밑으로 이어 붙일 강줄기.
 *
 * 강은 「길이 아닌 칸」에만 그린다. 그래서 길이 강을 가로지르는 자리에서는
 * 물이 뚝 끊겨, 다리가 강이 아니라 맨땅에 놓인 것처럼 보였다.
 * 여기 적은 선을 따라서는 길 위에도 물을 그려 강을 이어 준다 —
 * 통행 판정은 그대로(마스크)라 유닛은 다리 위를 정상적으로 건넌다.
 * (x0, y0) → (x1, y1) 을 잇는 굵기 halfW*2 의 띠. 좌표 단위는 타일.
 */
export interface WaterSpan {
  readonly x0: number; readonly y0: number;
  readonly x1: number; readonly y1: number;
  readonly halfW: number;
}

export const MAP_WATER_SPANS: Record<string, readonly WaterSpan[]> = {
  ashroad: [
    { x0: 19.5, y0: 1.0, x1: 20.2, y1: 7.6, halfW: 0.78 },  // 첫 나무다리 (다리 널판 안쪽으로)
    { x0: 70.0, y0: 1.0, x1: 72.5, y1: 7.4, halfW: 0.78 },  // 두 번째 다리 (강이 비스듬히 흐른다)
  ],
};

/** (x, y) 타일 좌표가 이어 붙인 강줄기 안인가. */
export function inWaterSpan(spans: readonly WaterSpan[], x: number, y: number): boolean {
  for (const s of spans) {
    const dx = s.x1 - s.x0;
    const dy = s.y1 - s.y0;
    const len2 = dx * dx + dy * dy;
    if (len2 <= 0) continue;
    let t = ((x - s.x0) * dx + (y - s.y0) * dy) / len2;
    if (t < 0) t = 0; else if (t > 1) t = 1;
    const px = s.x0 + dx * t;
    const py = s.y0 + dy * t;
    const ex = x - px;
    const ey = y - py;
    if (ex * ex + ey * ey <= s.halfW * s.halfW) return true;
  }
  return false;
}

